query SpendSummary($period: String!, $categoryIds: [String!], $departmentIds: [String!]) {
  transactions(period: $period, categoryIds: $categoryIds, departmentIds: $departmentIds)
  {
    totalAmount
    currency
    category
    bookedAt
  }
}

